/**
 * Title & Customer Name formatting utility for CRM modules.
 * Ensures consistent display of real Customer / Lead names instead of autogenerated
 * titles like "Quotation - Name - Opportunity" across tables, cards, dropdowns, and drawers.
 */

export function getCleanCustomerName(
  customer?: { name?: string | null; company?: string | null } | null,
  rawTitle?: string | null,
  leadName?: string | null
): string {
  // 1. If explicit customer name is available, prioritize it
  const cName = customer?.name?.trim();
  if (cName && cName !== "—" && cName !== "-" && !cName.toLowerCase().includes("opportunity")) {
    return cName;
  }

  // 2. If explicit lead name is available, use it
  const lName = leadName?.trim();
  if (lName && lName !== "—" && lName !== "-") {
    return lName;
  }

  // 3. Fallback to stripping legacy title artifacts
  let clean = (rawTitle || "").trim();
  if (!clean) return cName || "Customer";

  // Strip leading entity labels (Quotation -, Order -, Deal -, Invoice -)
  clean = clean.replace(/^(quotation|order|deal|invoice)\s*[-–—:]\s*/i, "");
  // Strip trailing " - Opportunity"
  clean = clean.replace(/\s*[-–—:]\s*opportunity\s*$/i, "");
  // Strip any remaining secondary label
  clean = clean.replace(/^(quotation|order|deal|invoice)\s*[-–—:]\s*/i, "");
  clean = clean.replace(/\s*[-–—:]\s*opportunity\s*$/i, "");

  return clean.trim() || cName || (rawTitle || "Customer");
}
